      write_status_text (STATUS_ENC_TO, buf);
    }

  if (!opt.list_only && !opt.override_session_key)
    {
      struct pubkey_enc_list *x = xmalloc (sizeof *x);

      x->keyid[0] = enc->keyid[0];
      x->keyid[1] = enc->keyid[1];
      x->pubkey_algo = enc->pubkey_algo;
